{{ config(materialized='view') }}

with t0 as (
    select
        case_id as HUB_CLAIM_BK__CASE_ID,
        inward_no
    from {{ ref('stg_hat_ocr_bill_details') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__CASE_ID order by HUB_CLAIM_BK__CASE_ID) = 1
),

t1 as (
    select
        claim_id as HUB_CLAIM_BK__CLAIM_ID,
        bill_status,
        cover_type,
        ocr_bill_no
    from {{ ref('stg_hm_bill_detail') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__CLAIM_ID order by HUB_CLAIM_BK__CLAIM_ID) = 1
),

t2 as (
