        ref_bill_id
    from {{ ref('stg_hm_bill_detail_ocr') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__CLAIM_ID order by HUB_CLAIM_BK__CLAIM_ID) = 1
),

t3 as (
