        partner_id as HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID,
        tpa_trans_key as HUB_FINANCIAL_TRANSACTION_BK__TPA_TRANS_KEY,
        tpa_claim_no as HUB_LOSS_EVENT_BK__TPA_CLAIM_NO,
        controlling_office as HUB_ORG_UNIT_BK__CONTROLLING_OFFICE,
