        customer_id as HUB_PARTY_BK__CUSTOMER_ID,
        hospital_code as HUB_PARTY_BK__HOSPITAL_CODE,
        cheque_no as HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO,
        policy_no as HUB_POLICY_BK__POLICY_NO,
        benefit_type
    from {{ ref('stg_tpa_claim_details_ws') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__BJAZ_CLAIM_ID, HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, HUB_FINANCIAL_TRANSACTION_BK__TPA_TRANS_KEY, HUB_LOSS_EVENT_BK__TPA_CLAIM_NO, HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO, HUB_POLICY_BK__POLICY_NO order by HUB_CLAIM_BK__BJAZ_CLAIM_ID, HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, HUB_FINANCIAL_TRANSACTION_BK__TPA_TRANS_KEY, HUB_LOSS_EVENT_BK__TPA_CLAIM_NO, HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO, HUB_POLICY_BK__POLICY_NO) = 1
),

t4 as (
