        pd_location_code as HUB_ORG_UNIT_BK__PD_LOCATION_CODE,
        pd_bagic_rm_e_code as HUB_PARTY_BK__PD_BAGIC_RM_E_CODE,
        pd_imd_rm_e_code as HUB_PARTY_BK__PD_IMD_RM_E_CODE,
