    qualify row_number() over (partition by HUB_ASSESSMENT_BK__PD_SCRUTINY_NUMBER, HUB_DISTRIBUTION_CHANNEL_BK__PD_PARTNER_ID, HUB_FINANCIAL_ACCOUNT_BK__PLC_LOAN_ACC_NO, HUB_ORG_UNIT_BK__PD_LOCATION_CODE, HUB_POLICY_BK__POL_SERIAL_NO, HUB_PRODUCT_BK__PD_PRODUCT_CODE order by HUB_ASSESSMENT_BK__PD_SCRUTINY_NUMBER, HUB_DISTRIBUTION_CHANNEL_BK__PD_PARTNER_ID, HUB_FINANCIAL_ACCOUNT_BK__PLC_LOAN_ACC_NO, HUB_ORG_UNIT_BK__PD_LOCATION_CODE, HUB_POLICY_BK__POL_SERIAL_NO, HUB_PRODUCT_BK__PD_PRODUCT_CODE) = 1
