        nullif(trim(REG_NO),'') as HUB_POLICY_BK__REG_NO,
        nullif('PRODUCT:' || nullif(trim(PRODUCT),''), 'PRODUCT:') as HUB_PRODUCT_BK__PRODUCT,
        nullif(trim(QUOTE_NO),'') as HUB_QUOTE_BK__QUOTE_NO,
        coverage
    from {{ ref('stg_grp_hlt_mem_dtls') }}
    qualify row_number() over (partition by HUB_COVERAGE_BK__COVERAGE, HUB_POLICY_BK__REG_NO, HUB_PRODUCT_BK__PRODUCT, HUB_QUOTE_BK__QUOTE_NO order by HUB_COVERAGE_BK__COVERAGE, HUB_POLICY_BK__REG_NO, HUB_PRODUCT_BK__PRODUCT, HUB_QUOTE_BK__QUOTE_NO) = 1
),

t7 as (
