    qualify row_number() over (partition by HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, HUB_PARTY_BK__MEMBER_NO, HUB_POLICY_BK__CONTRACT_ID, HUB_RISK_OBJECT_BK__MEMBER_NO order by HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, HUB_PARTY_BK__MEMBER_NO, HUB_POLICY_BK__CONTRACT_ID, HUB_RISK_OBJECT_BK__MEMBER_NO) = 1
