    qualify row_number() over (partition by HUB_COVERAGE_BK__COVER_CODE order by HUB_COVERAGE_BK__COVER_CODE) = 1
)

select
    coalesce(t4.HUB_ASSESSMENT_BK__PD_SCRUTINY_NUMBER, t5.HUB_ASSESSMENT_BK__SCRUTINY_NO) as HUB_ASSESSMENT_BK,
    coalesce(t0.HUB_CLAIM_BK__CASE_ID, t1.HUB_CLAIM_BK__CLAIM_ID, t2.HUB_CLAIM_BK__CLAIM_ID, t3.HUB_CLAIM_BK__BJAZ_CLAIM_ID) as HUB_CLAIM_BK,
    coalesce(t6.HUB_COVERAGE_BK__COVERAGE, t8.HUB_COVERAGE_BK__COVER_CODE) as HUB_COVERAGE_BK,
