    coalesce(t3.HUB_POLICY_BK__POLICY_NO, t4.HUB_POLICY_BK__POL_SERIAL_NO, t6.HUB_POLICY_BK__REG_NO, t7.HUB_POLICY_BK__CONTRACT_ID) as HUB_POLICY_BK,
    coalesce(t4.HUB_PRODUCT_BK__PD_PRODUCT_CODE, t5.HUB_PRODUCT_BK__PRODUCT, t6.HUB_PRODUCT_BK__PRODUCT) as HUB_PRODUCT_BK,
