    t7.HUB_RISK_OBJECT_BK__MEMBER_NO as HUB_RISK_OBJECT_BK,
    t3.HUB_ORG_UNIT_BK__CONTROLLING_OFFICE as T3__HUB_ORG_UNIT_BK__CONTROLLING_OFFICE,
    t3.HUB_ORG_UNIT_BK__OPERATING_OFFICE as T3__HUB_ORG_UNIT_BK__OPERATING_OFFICE,
    t3.HUB_PARTY_BK__CUSTOMER_ID as T3__HUB_PARTY_BK__CUSTOMER_ID,
