from t0
full outer join t1 on t1.HUB_CLAIM_BK__CLAIM_ID = t0.HUB_CLAIM_BK__CASE_ID
full outer join t2 on t2.HUB_CLAIM_BK__CLAIM_ID = coalesce(t0.HUB_CLAIM_BK__CASE_ID, t1.HUB_CLAIM_BK__CLAIM_ID)
full outer join t3 on t3.HUB_CLAIM_BK__BJAZ_CLAIM_ID = coalesce(t0.HUB_CLAIM_BK__CASE_ID, t1.HUB_CLAIM_BK__CLAIM_ID, t2.HUB_CLAIM_BK__CLAIM_ID)
