full outer join t7 on t7.HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID = coalesce(t3.HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, t4.HUB_DISTRIBUTION_CHANNEL_BK__PD_PARTNER_ID)
full outer join t8 on t8.HUB_COVERAGE_BK__COVER_CODE = t6.HUB_COVERAGE_BK__COVERAGE
